<div class="page-heading"><h1>Sertifikat Saya</h1><p>Sertifikat diterbitkan setelah persyaratan pembelajaran dan kelulusan terpenuhi serta disetujui admin.</p></div>
<?php $certificates=rows("SELECT c.* FROM certificates c JOIN enrollments en ON en.id=c.enrollment_id JOIN registrations r ON r.id=en.registration_id WHERE r.user_id=? AND r.status='approved' AND en.status='completed' AND c.revoked_at IS NULL ORDER BY c.issued_at DESC",[$uid]);if(!$certificates)emptyState('Belum ada sertifikat diterbitkan','Selesaikan aktivitas dan evaluasi pelatihan. Sertifikat yang sudah disetujui admin akan muncul di sini.','portal.php?view=training','Lihat kemajuan pelatihan'); ?>
<div class="portal-grid"><?php foreach($certificates as $certificate): ?><article class="panel"><span class="badge approved">Terverifikasi</span><h2 style="margin-top:18px"><?= e($certificate['program_name']) ?></h2><p><?= e($certificate['participant_name']) ?></p><p class="muted"><?= e($certificate['certificate_number']) ?></p><p class="muted">Diterbitkan <?= e($certificate['issued_at']) ?></p><img class="certificate-qr" src="verify.php?token=<?= e($certificate['verification_token']) ?>&amp;qr=1" alt="QR verifikasi sertifikat"><div class="actions"><a class="btn" href="download.php?kind=certificate&amp;id=<?= (int)$certificate['id'] ?>">Unduh PDF</a><a class="btn secondary" href="verify.php?token=<?= e($certificate['verification_token']) ?>">Verifikasi</a></div></article><?php endforeach; ?></div>
